export type IconId = string;
export const ICONS: Record<string, { C: LucideIcon; label: string; group: string }> = Object.fromEntries(ICON_ROWS.map((r) => [r[0], { C: COMP[OF[r[0]]], label: r[2], group: r[1] }]));
/** Colourful, "real" icons: the same ids drawn as colour emoji. */
export const EMOJI: Record<string, string> = Object.fromEntries(ICON_ROWS.map((r) => [r[0], r[3]]));
export const iconLabel = (id: string) => ICONS[id]?.label ?? BRAND_LABELS[id] ?? id;
export type IconStyle = "line" | "duo" | "emoji" | "3d";
export const ICON_STYLES: [IconStyle, string][] = [["line", "خطّية"], ["duo", "معبّاة"], ["emoji", "ملوّنة طبيعية"], ["3d", "3D احترافية"]];
export const IconStyleContext = createContext<{ style: IconStyle; images?: Record<string, string> }>({ style: "line" });
export const EMOJI_FONT = `"Noto Color Emoji", "Apple Color Emoji", "Segoe UI Emoji", sans-serif`;

/** a service logo: filled with the design colour (line / duo), or on its own colour tile (colour / 3D styles) */
function BrandGlyph({ id, size, color }: { id: string; size: number; color: string }) {
  const { style } = useContext(IconStyleContext);
  const b = DESIGN_BRANDS[id];
  const tile = style === "emoji" || style === "3d";
  const bg = b.hex === "000000" ? "111111" : b.hex;
  const dark = bg === "FFFC00";
  return tile ? (
    <span style={{ width: size, height: size, borderRadius: size * 0.26, background: `#${bg}`, display: "inline-flex", alignItems: "center", justifyContent: "center", flex: "none" }}>
      <svg width={size * 0.64} height={size * 0.64} viewBox="0 0 24 24"><path d={b.path} fill={dark ? "#111" : "#fff"} /></svg>
    </span>
  ) : (
    <svg width={size} height={size} viewBox="0 0 24 24" style={{ flex: "none" }}><path d={b.path} fill={color} /></svg>
  );
}

export function DIcon({ name, size, color, stroke = 1.8 }: { name?: string; size: number; color: string; stroke?: number }) {
  const { style, images } = useContext(IconStyleContext);
  if (name && name in DESIGN_BRANDS) return <BrandGlyph id={name} size={size} color={color} />;
  const id = (name && name in ICONS ? name : "sparkles") as IconId;
  if (style === "3d" && images?.[id]) return <Img src={images[id]} style={{ width: size * 1.6, height: size * 1.6, objectFit: "contain", flex: "none", margin: -size * 0.3 }} />;
  if (style === "emoji" && COLOR_ICONS[id]) return <svg viewBox="0 0 32 32" width={size * 1.1} height={size * 1.1} style={{ flex: "none", display: "inline-block", margin: -size * 0.05 }} aria-hidden dangerouslySetInnerHTML={{ __html: COLOR_ICONS[id] }} />;
  if (style === "emoji") return <span style={{ fontSize: size * 0.92, lineHeight: 1, fontFamily: EMOJI_FONT, flex: "none", display: "inline-block", width: size, textAlign: "center" }}>{EMOJI[id]}</span>;
  const C = ICONS[id].C;
  return <C size={size} color={color} strokeWidth={stroke} absoluteStrokeWidth={false} fill={style === "duo" || style === "3d" ? color : "none"} fillOpacity={style === "duo" || style === "3d" ? 0.22 : undefined} style={{ flex: "none" }} />;
}
